#!/usr/bin/env bash
# rustfmt of the Rust files a change touches, compared with the main commit it branched from:
# what t's `fmt-changed` check runs before a push (.githooks/pre-push), in seconds where the
# whole tree's `cargo fmt --check` takes a minute. It needs Git: under t, the check's `git = true`
# makes `main` the commit the change branched from, with the change in the working tree.
#
# As in .githooks/pre-commit, vendored crates and sources marked `@generated` keep their own
# formatting; what tilo-app generates is formatted like any module.
#
# Usage: fmt-changed.sh --check   fail if one of them isn't formatted
#        fmt-changed.sh           format them
set -euo pipefail

mode=()
case "${1:-}" in
    --check) mode=(--check) ;;
    "") ;;
    *) echo "usage: fmt-changed.sh [--check]" >&2; exit 2 ;;
esac

files=()
while IFS= read -r -d '' file; do
    [ -f "$file" ] || continue
    head5=$(head -n 5 -- "$file" || true)
    case "$head5" in
        *"@generated by tilo-app"*) ;;
        *@generated*) continue ;;
    esac
    files+=("$file")
done < <({
    git diff --name-only -z --diff-filter=ACMRTUXB main -- '*.rs' ':(top,exclude)vendor/**'
    git ls-files --others --exclude-standard -z -- '*.rs' ':(top,exclude)vendor/**'
} | sort -zu)

if [ "${#files[@]}" -eq 0 ]; then
    echo "changed Rust formatting OK (no hand-written Rust file changed)"
    exit 0
fi
rustfmt --edition 2024 "${mode[@]}" -- "${files[@]}"
echo "changed Rust formatting OK (${#files[@]} files)"
